function openDrawer(title,html) {
 lastFocus=document.activeElement;
 $('#drawer').innerHTML='<div class="drawer-head"><h2 id="drawer-title">'+title+'</h2><button class="close" data-close aria-label="Fechar painel">×</button></div><div class="drawer-body">'+html+'</div>';
 $('#drawer').showModal(); $('#drawer [data-close]').onclick=()=>$('#drawer').close();
}
