function handoff(destination,s=null,entityId=null) {
 const entityName=entityId?entity(entityId).name:null;
 const context=s?'<div class="panel handoff-context"><div class="eyebrow">Contexto que será levado</div><p><strong>Sinal:</strong> '+s.title+'</p><p><strong>Entidades:</strong> '+(s.entityLabel||s.entities.map(id=>entity(id).name).join(' · '))+'</p><p><strong>Fonte:</strong> '+s.source+' · '+s.date+'</p><p><strong>Recorte:</strong> Atlas Componentes · '+(s.id==='p1'?'julho e agosto/2026 · mesmo corredor/modal/serviço':'corte em 13/09/2026 · janela da necessidade quando vinculada')+'</p><p><strong>Questão:</strong> '+s.next+'</p></div>':'';
 openDrawer('Conexão com '+destination,'<span class="pill purple">Ponto de conexão · demonstração</span><p style="margin-top:18px">'+(entityName?'Destino proposto: <strong>'+entityName+'</strong>. ':'')+(destination.includes('Cotações')?'Abriria a revisão de uma cotação com os dados conhecidos, sujeita à confirmação. Nenhuma solicitação foi criada ou enviada.':destination.includes('Inteligência')?'A ficha ou cenário aprofundado abre em Inteligência, com o recorte e as evidências do sinal. Essa análise não é reproduzida no Radar.':'Este módulo está representado apenas como destino de navegação nesta prévia.')+'</p>'+context+'<div class="note">O módulo de destino não foi modificado. Esta passagem é um contrato de navegação para revisão, ainda sem conexão implementada.</div><div class="drawer-actions"><button class="button" id="return-signal">Voltar '+(s?'ao sinal':'ao Radar')+'</button></div>');
 $('#return-signal').onclick=()=>$('#drawer').close();
}
const destinationFor = s => s.target==='cenário'?'Inteligência · cenário relacionado':s.target==='rota'?'Inteligência · Rotas e locais':'Inteligência · Parceiros';
